def _social_account_email(account: SocialAccount) -> str:
    extra_data = account.extra_data or {}
    email = extra_data.get("email")
    return str(email or "")


def _social_account_avatar_url(account: SocialAccount) -> str:
    extra_data = account.extra_data or {}
    picture = extra_data.get("picture")
    if isinstance(picture, dict):
        picture = picture.get("data", {}).get("url")
    return str(picture or extra_data.get("avatar_url") or "")


def _social_account_display_name(account: SocialAccount) -> str:
    extra_data = account.extra_data or {}
    provider_labels = {"google": "Google", "apple": "Apple"}
    return str(
        extra_data.get("name")
        or _social_account_email(account)
        or provider_labels.get(account.provider, account.provider.title())
    )


