        _upsert_connected_social_account(
            user=user,
            provider="apple",
            uid=str(claims["sub"]),
            extra_data=claims,
        )
    except PermissionDenied as exc:
        return Response(
            {"detail": str(exc)},
            status=status.HTTP_409_CONFLICT,
        )
    except ValueError as exc:
        return Response(
            {"detail": str(exc)},
