def _upsert_connected_social_account(
    *, user: User, provider: str, uid: str, extra_data: dict[str, Any]
) -> None:
    existing_for_uid = (
        SocialAccount.objects.filter(provider=provider, uid=uid)
        .exclude(user=user)
        .first()
    )
    if existing_for_uid is not None:
        raise PermissionDenied(
            "This provider account is already linked to another user."
        )

    SocialAccount.objects.update_or_create(
        user=user,
        provider=provider,
        defaults={"uid": uid, "extra_data": extra_data},
    )


