class FamilyTaskViewSet(FeatureRequiredMixin, viewsets.ModelViewSet[FamilyTask]):
    required_feature = "organize"
    serializer_class = FamilyTaskSerializer
    permission_classes = [permissions.IsAuthenticated]
    COMPLETED_CAP = 20

    def get_queryset(self) -> QuerySet[FamilyTask]:
        user = cast(User, self.request.user)
        return FamilyTask.objects.filter(
            family_id__in=get_accessible_family_ids(user)
        ).select_related("family", "assigned_to", "created_by", "linked_event")

    def _truthy_param(self, name: str) -> bool:
        return str(self.request.query_params.get(name, "")).lower() in {
            "1",
            "true",
            "yes",
            "on",
        }

    def _apply_bucket_filter(
        self, queryset: QuerySet[FamilyTask]
    ) -> QuerySet[FamilyTask]:
        bucket = self.request.query_params.get("bucket")
        now = timezone.now()
        if bucket == "today":
            return queryset.filter(
                due_at__isnull=False,
                due_at__date=timezone.localdate(now),
            )
        if bucket == "overdue":
            return queryset.filter(due_at__lt=now)
        if bucket == "this_week":
            return queryset.filter(
                due_at__isnull=False,
                due_at__gte=now,
                due_at__lte=now + timedelta(days=7),
            )
        return queryset

    def _apply_assignee_filter(
        self, queryset: QuerySet[FamilyTask]
    ) -> QuerySet[FamilyTask]:
        assignee = self.request.query_params.get("assignee")
        if not assignee or assignee == "all":
            return queryset
        if assignee == "me":
            user = cast(User, self.request.user)
            return queryset.filter(assigned_to=user)
        if assignee == "unassigned":
            return queryset.filter(assigned_to__isnull=True)
        try:
            assignee_id = int(assignee)
        except (TypeError, ValueError):
            return queryset.none()
        return queryset.filter(assigned_to_id=assignee_id)

    def list(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        base = self._apply_assignee_filter(self.get_queryset())
        base = self._apply_bucket_filter(base)

        explicit_status = request.query_params.get("status")
        include_completed = self._truthy_param("include_completed")

        if explicit_status:
            # Caller wants exactly one status. Cap completed/cancelled to the
            # most recent COMPLETED_CAP so the payload is bounded.
            filtered = base.filter(status=explicit_status)
            if explicit_status in (
                FamilyTask.Status.COMPLETED,
                FamilyTask.Status.CANCELLED,
            ):
                filtered = filtered.order_by("-completed_at", "-updated_at")[
                    : self.COMPLETED_CAP
                ]
            tasks = list(filtered)
        elif include_completed:
            # Active tasks (unbounded) + most-recent completed (capped).
            active = list(base.filter(status=FamilyTask.Status.PENDING))
            completed = list(
                base.filter(status=FamilyTask.Status.COMPLETED).order_by(
                    "-completed_at", "-updated_at"
                )[: self.COMPLETED_CAP]
            )
            tasks = active + completed
        else:
            # Default: hide completed/cancelled entirely.
            tasks = list(base.filter(status=FamilyTask.Status.PENDING))

        serializer = self.get_serializer(tasks, many=True)
        return Response(serializer.data)

    def perform_create(self, serializer: BaseSerializer[FamilyTask]) -> None:
        serializer.save()
        _invalidate_organize_workspace_cache(cast(User, self.request.user))

    def perform_update(self, serializer: BaseSerializer[FamilyTask]) -> None:
        assert serializer.instance is not None
        old_status = serializer.instance.status
        task = serializer.save()
        if (
            old_status != FamilyTask.Status.COMPLETED
            and task.status == FamilyTask.Status.COMPLETED
            and task.recurrence != FamilyTask.Recurrence.NONE
        ):
            spawn_next_occurrence(task)
        _invalidate_organize_workspace_cache(cast(User, self.request.user))

    def perform_destroy(self, instance: FamilyTask) -> None:
        instance.delete()
        _invalidate_organize_workspace_cache(cast(User, self.request.user))

    @action(detail=False, methods=["post"], url_path="create-from-household-action")
    def create_from_household_action(self, request: Request) -> Response:
        serializer = HouseholdActionTaskSerializer(
            data=request.data, context=self.get_serializer_context()
        )
        serializer.is_valid(raise_exception=True)
