            linked_event=serializer.validated_data.get("linked_event"),
            created_by=cast(User, request.user),
            source_client_app=getattr(request, "client_app", "house"),
        )
        _invalidate_organize_workspace_cache(cast(User, request.user))
        response_serializer = self.get_serializer(task)
        return Response(response_serializer.data, status=status.HTTP_201_CREATED)


