    parser_classes = [JSONParser, FormParser, MultiPartParser]

    def get_queryset(self) -> QuerySet[InboxCapture]:
        user = cast(User, self.request.user)
        queryset = InboxCapture.objects.filter(
            family_id__in=get_accessible_family_ids(user)
        ).select_related(
            "family",
            "created_by",
            "converted_task",
            "converted_grocery_list",
            "converted_event",
        )
        status_filter = self.request.query_params.get("status")
        if status_filter:
            queryset = queryset.filter(status=status_filter)
        return queryset

    def list(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        cached_payload = get_desktop_response_cache(
            request,
            namespace=ORGANIZE_WORKSPACE_CACHE_NAMESPACE,
            scope_token=cast(User, request.user).id,
        )
        if cached_payload is not None:
            return Response(cached_payload)

        response = super().list(request, *args, **kwargs)
        if response.status_code == status.HTTP_200_OK:
            set_desktop_response_cache(
                request,
                namespace=ORGANIZE_WORKSPACE_CACHE_NAMESPACE,
                scope_token=cast(User, request.user).id,
                payload=response.data,
            )
        return response

    def perform_create(self, serializer: BaseSerializer[InboxCapture]) -> None:
        serializer.save()
        _invalidate_organize_workspace_cache(cast(User, self.request.user))

    def perform_destroy(self, instance: InboxCapture) -> None:
        instance.delete()
        _invalidate_organize_workspace_cache(cast(User, self.request.user))

    @action(detail=False, methods=["post"], url_path="desktop")
    def desktop(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        serializer = DesktopCaptureSerializer(
            data=request.data, context=self.get_serializer_context()
        )
        serializer.is_valid(raise_exception=True)
        capture = DesktopInboxCaptureSerializer(
            context=self.get_serializer_context()
        ).create(serializer.validated_data)
        _invalidate_organize_workspace_cache(cast(User, request.user))
        return Response(
            self.get_serializer(capture).data, status=status.HTTP_201_CREATED
        )

    @action(detail=False, methods=["post"], url_path="task-photo")
    def task_photo(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        serializer = TaskPhotoCaptureSerializer(
            data=request.data, context=self.get_serializer_context()
        )
        serializer.is_valid(raise_exception=True)

        family = get_default_family_for_user(cast(User, request.user))
        if family is None:
            return Response(
                {"detail": "No active family found for this user."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            capture = InboxCapture.objects.create(
                family=family,
                created_by=cast(User, request.user),
                capture_type=InboxCapture.CaptureType.PHOTO,
                status=InboxCapture.Status.CAPTURED,
                raw_text=serializer.validated_data.get("raw_text", ""),
                raw_payload=serializer.validated_data.get("raw_payload", {}),
                source_client_app=getattr(request, "client_app", ""),
                photo=serializer.validated_data["photo"],
            )
        except Exception:
            logger.error(
                "Unable to create task photo capture.",
                exc_info=True,
                **build_task_photo_log_context(
                    operation="task_photo_create_capture",
                    user=cast(User, request.user),
                    family=family,
                ),
            )
            return Response(
                {"detail": "We couldn't start task extraction right now."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        result = TaskPhotoExtractionService.process_capture(capture)
        if not result["success"]:
            if capture.photo:
                capture.photo.delete(save=False)
            capture.delete()
            return Response(
                {"detail": result["error"]},
                status=result.get("status_code", status.HTTP_400_BAD_REQUEST),
            )

        capture.refresh_from_db()
        _invalidate_organize_workspace_cache(cast(User, request.user))
        return Response(
            self.get_serializer(capture).data, status=status.HTTP_201_CREATED
        )

    @action(detail=True, methods=["post"], url_path="create-tasks")
    def create_tasks(self, request: Request, pk: str | None = None) -> Response:
        capture = self.get_object()
        serializer = TaskSuggestionsCreateSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        try:
            created_tasks = create_tasks_from_capture(
                capture,
                reviewed_tasks=serializer.validated_data["tasks"],
            )
        except TaskCaptureCreateError as exc:
            logger.warning(
                "Unable to create tasks from capture: %s",
                exc.detail,
                **build_task_photo_log_context(
                    operation="task_photo_create_tasks",
                    capture=capture,
                    user=cast(User, request.user),
                    family=capture.family,
                ),
            )
            return Response({"detail": exc.detail}, status=status.HTTP_400_BAD_REQUEST)
        except Exception:
            logger.error(
                "Unable to create tasks from capture.",
                exc_info=True,
                **build_task_photo_log_context(
                    operation="task_photo_create_tasks",
                    capture=capture,
                    user=cast(User, request.user),
                    family=capture.family,
                ),
            )
            return Response(
                {"detail": "Unable to create tasks from capture."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        capture.refresh_from_db()
        _invalidate_organize_workspace_cache(cast(User, request.user))
        response = self.get_serializer(capture).data
        response["tasks"] = FamilyTaskSerializer(
            created_tasks, many=True, context=self.get_serializer_context()
        ).data
        return Response(response, status=status.HTTP_201_CREATED)

    @action(detail=True, methods=["post"])
    def convert(self, request: Request, pk: str | None = None) -> Response:
        capture = self.get_object()
        serializer = CaptureConversionSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        validated = serializer.validated_data
        target_kind = normalize_capture_target_kind(validated["target_kind"])
        proposal_index = validated.get("proposal_index", 0)

        try:
            if target_kind == "grocery_list":
                list_payload = build_capture_list_payload(
                    capture,
                    proposal_index=proposal_index,
                    title=validated.get("title"),
                    notes=validated.get("notes"),
                    items=validated.get("items"),
                )
                grocery_list = convert_capture_to_grocery_list(
                    capture,
                    name=list_payload["name"],
                    description=list_payload["description"],
                    owner=cast(User, request.user),
                    items=list_payload["items"],
                )
                payload = self.get_serializer(capture).data
                payload["grocery_list"] = GroceryListSummarySerializer(
                    grocery_list
                ).data
                _invalidate_organize_workspace_cache(cast(User, request.user))
                return Response(payload)

            if target_kind == "event":
                event_payload = build_capture_event_payload(
                    capture,
                    proposal_index=proposal_index,
                    title=validated.get("title"),
                    notes=validated.get("notes"),
                    starts_at=validated.get("starts_at"),
                    ends_at=validated.get("ends_at"),
                    location=validated.get("location"),
                )
                event = convert_capture_to_event(
                    capture,
                    event_payload,
                    source_client_app=getattr(request, "client_app", "organize"),
                )
                payload = self.get_serializer(capture).data
                payload["event"] = EventSummarySerializer(
                    event, context=self.get_serializer_context()
                ).data
                _invalidate_organize_workspace_cache(cast(User, request.user))
                return Response(payload)

            task_payload = build_capture_task_payload(
                capture,
                proposal_index=proposal_index,
                title=validated.get("title"),
                notes=validated.get("notes"),
            )
            task = convert_capture_to_task(
                capture,
                title=task_payload["title"],
                notes=task_payload["notes"],
            )
        except ValueError as exc:
            return Response({"detail": str(exc)}, status=status.HTTP_400_BAD_REQUEST)

        payload = self.get_serializer(capture).data
        payload["task"] = FamilyTaskSerializer(
            task, context=self.get_serializer_context()
        ).data
        _invalidate_organize_workspace_cache(cast(User, request.user))
        return Response(payload)

    @action(detail=True, methods=["post"])
    def dismiss(self, request: Request, pk: str | None = None) -> Response:
        capture = dismiss_capture(self.get_object())
        _invalidate_organize_workspace_cache(cast(User, request.user))
        serializer = self.get_serializer(capture)
        return Response(serializer.data)


